func TestUDPBatchConcurrentWriteClose(t *testing.T) {
	receiver, err := net.ListenUDP("udp4", &net.UDPAddr{IP: net.IPv4(127, 0, 0, 1)})
	if err != nil {
		t.Fatal(err)
	}
	defer receiver.Close()
	raw, err := net.ListenPacket("udp4", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	c := wrapUDPPacketConn(raw).(*batchUDPConn)
	defer c.Close()
	peer := &udpPacketPeer{addr: receiver.LocalAddr().(*net.UDPAddr), grouped: true}
	start := make(chan struct{})
	firstWrite := make(chan struct{})
	var first sync.Once
	var wg sync.WaitGroup
	for i := 0; i < 256; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			b := bytes.Repeat([]byte{42}, 32)
			for j := 0; j < 30; j++ {
				_, err := c.WriteTo(b, peer)
				first.Do(func() { close(firstWrite) })
				clear(b) // Write must have finished consuming these bytes before returning.
				if err != nil && !errors.Is(err, net.ErrClosed) {
					t.Error(err)
				}
			}
		}()
	}
	close(start)
	<-firstWrite
	done := make(chan struct{})
	go func() { c.Close(); wg.Wait(); close(done) }()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("queued writes did not stop on close")
	}
}

func TestUDPBatchPartialSendDoesNotDropOtherPeers(t *testing.T) {
