	if err != nil {
		t.Fatal(err)
	}
	defer receiver.Close()
	raw, err := net.ListenPacket("udp4", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	c := wrapUDPPacketConn(raw).(*batchUDPConn)
	defer c.Close()
	peers := []*net.UDPAddr{receiver.LocalAddr().(*net.UDPAddr), {IP: net.IPv4(127, 0, 0, 1), Port: 0}, receiver.LocalAddr().(*net.UDPAddr)}
	jobs := make([]*udpWriteRequest, len(peers))
	for i, peer := range peers {
		jobs[i] = &udpWriteRequest{data: []byte{byte(i)}, peer: &udpPacketPeer{addr: peer}, done: make(chan udpWriteResult, 1)}
		c.writes <- jobs[i]
	}
	c.writerOnce.Do(func() { go c.writeLoop() })
	for i, job := range jobs {
		select {
		case result := <-job.done:
			if i == 1 {
				if result.err == nil {
					t.Fatal("bad peer unexpectedly succeeded")
				}
			} else if result.err != nil || result.n != 1 {
				t.Fatalf("good peer %d failed: %+v", i, result)
			}
		case <-time.After(time.Second):
			t.Fatal("write completion missing")
		}
	}
	receiver.SetReadDeadline(time.Now().Add(time.Second))
	b := make([]byte, 4)
	for _, want := range []byte{0, 2} {
		n, _, err := receiver.ReadFromUDP(b)
		if err != nil || n != 1 || b[0] != want {
			t.Fatalf("good reply dropped after bad peer: %d %v", n, err)
		}
	}
}

