	done chan udpWriteResult
}

var udpWriteRequests = sync.Pool{New: func() any { return &udpWriteRequest{done: make(chan udpWriteResult, 1)} }}

func (c *batchUDPConn) writeQueued(b []byte, peer *udpPacketPeer) (int, error) {
	job := udpWriteRequests.Get().(*udpWriteRequest)
	job.data, job.peer = b, peer
	c.enqueueMu.RLock()
	if c.closed.Load() {
		c.enqueueMu.RUnlock()
		job.data, job.peer = nil, nil
		udpWriteRequests.Put(job)
		return 0, net.ErrClosed
	}
	c.writerOnce.Do(func() { go c.writeLoop() })
	queued := false
	select {
	case c.writes <- job:
		queued = true
	case <-c.closing:
	}
	c.enqueueMu.RUnlock()
	result := udpWriteResult{err: net.ErrClosed}
	if queued {
		result = <-job.done
	}
	job.data, job.peer = nil, nil
	udpWriteRequests.Put(job)
	return result.n, result.err
}

// A caller retains its bytes until acknowledged. There is no batching timer:
// let runnable handlers enqueue, then send only the packets already waiting.
func (c *batchUDPConn) writeLoop() {
	defer close(c.writerDone)
	var jobs [udpReadBatchSize]*udpWriteRequest
	var messages [udpReadBatchSize]ipv4.Message
	var buffers [udpReadBatchSize][1][]byte
	for i := range messages {
		messages[i].Buffers = buffers[i][:]
